// viz-types: metro horizontal bars, share path multi-line, SFR vs all-SF scatter, ZIP tip bars, operator ladder, region rollup | layout: default

type ViewId = "metros" | "path" | "zips" | "operators" | "defs";
type DefFilter = OwnerDef | "all";
type PathMetro =
  | "jacksonville"
  | "phoenix"
  | "dallas"
  | "nashville"
  | "cincinnati"
  | "seattle"
  | "all";
type ZipSort = "share" | "year" | "beds";

const NAVY = "#1e3a5f";
const TEAL = "#0f766e";
const AMBER = "#b45309";
const ROSE = "#be123c";
const SLATE = "#64748b";
const SKY = "#0369a1";
const PATH_COLORS: Record<Exclude<PathMetro, "all">, string> = {
  jacksonville: ROSE,
  phoenix: AMBER,
  dallas: TEAL,
  nashville: SKY,
  cincinnati: SLATE,
  seattle: NAVY,
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

