                  />
                  <Scatter data={SHARE_SCATTER} fill={TEAL}>
                    {SHARE_SCATTER.map((p) => (
                      <Cell
                        key={p.metro}
                        fill={p.metro === "Atlanta" ? ROSE : TEAL}
                      />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "path" && (
